package com.smartmerchant.saas.iam.config;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.smartmerchant.saas.iam.domain.*; import com.smartmerchant.saas.iam.infrastructure.*; import com.smartmerchant.saas.security.Ids; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Configuration @ConditionalOnProperty(name="saas.bootstrap-admin.enabled",havingValue="true") public class BootstrapAdminConfiguration implements ApplicationRunner {
 private final UserAccountMapper users;private final TenantUserMapper members;private final RoleMapper roles;private final PermissionMapper permissions;private final PasswordEncoder encoder;private final JdbcTemplate jdbc;private final String username;private final String password;
 public BootstrapAdminConfiguration(UserAccountMapper u,TenantUserMapper m,RoleMapper r,PermissionMapper p,PasswordEncoder e,JdbcTemplate j,@Value("${saas.bootstrap-admin.username:platform-admin}")String name,@Value("${saas.bootstrap-admin.password}")String pass){users=u;members=m;roles=r;permissions=p;encoder=e;jdbc=j;username=name;password=pass;}
 @Override @Transactional public void run(ApplicationArguments args){if(users.selectCount(Wrappers.<UserAccount>lambdaQuery().eq(UserAccount::getUsername,username))>0)return;var now=LocalDateTime.now();var user=new UserAccount();user.setId(Ids.next());user.setUsername(username);user.setPasswordHash(encoder.encode(password));user.setDisplayName("平台超级管理员");user.setStatus("ACTIVE");user.setTokenVersion(0);user.setCreatedAt(now);user.setUpdatedAt(now);users.insert(user);var member=new TenantUser();member.setId(Ids.next());member.setTenantId(0L);member.setUserId(user.getId());member.setMemberType("PLATFORM_ADMIN");member.setDataScope("TENANT_ALL");member.setStatus("ACTIVE");member.setCreatedAt(now);member.setUpdatedAt(now);members.insert(member);var role=roles.selectOne(Wrappers.<Role>lambdaQuery().eq(Role::getTenantId,0L).eq(Role::getRoleCode,"PLATFORM_SUPER_ADMIN"));if(role==null){role=new Role();role.setId(Ids.next());role.setTenantId(0L);role.setRoleCode("PLATFORM_SUPER_ADMIN");role.setRoleName("平台超级管理员");role.setPlatformRole(true);role.setStatus("ACTIVE");role.setCreatedAt(now);role.setUpdatedAt(now);roles.insert(role);for(var permission:permissions.selectList(Wrappers.<Permission>lambdaQuery().eq(Permission::getAudience,"PLATFORM")))jdbc.update("INSERT INTO role_permission(tenant_id,role_id,permission_id) VALUES (0,?,?)",role.getId(),permission.getId());}jdbc.update("INSERT INTO user_role(tenant_id,user_id,role_id) VALUES (0,?,?)",user.getId(),role.getId());}
}
